```python
import ast

def check_idioms(code):
    # Initialize idiom violations dictionary
    idiom_violations = {'E401': {}}

    # Parse the code
    tree = ast.parse(code)

    # Check for E401: Multiple imports on one line
    for node in tree.body:
        if isinstance(node, ast.Import):
            if len(node.names) != len(node specifiers):
                idiom_violations['E401']['line'] = node.lineno
                idiom_violations['E401']['fix'] = []
                idiom_violations['E401']['fix'].append(f"Move imports to separate lines")

    return idiom_violations

def print_idiom_violations(violations):
    print("### Final Idiom Violations Found")
    for idiom, violations in violations.items():
        print(f"**Idiom {idiom} Violations:**")
        if len(violations) == 0:
            print("NO VIOLATIONS FOUND")
        else:
            for line, fix in violations.items():
                print(f"  * Line {line}: {fix}")

def main():
    # Load the code
    with open("code.py", "r") as file:
        code = file.read()

    # Check for idiom violations
    violations = check_idioms(code)
    print_idiom_violations(violations)

if __name__ == "__main__":
    main()
```

To use this script, replace `"code.py"` with the path to your code file. The script will print the idiom violations found in the code, along with suggested fixes.

