import ast

def detect_idioms(code):
    violations = {}

    tree = ast.parse(code)

    for node in ast.walk(tree):
        if isinstance(node, ast.Lambda):
            if node.name:
                line = node.lineno
                if node.name not in violations:
                    violations[node.name] = []
                violations[node.name].append(line)

    return violations

def fix_idioms(violations):
    fixes = {}
    for idiom, lines in violations.items():
        if len(lines) > 1:
            fixes[idiom] = ["\n".join(["# {}".format(line) for line in lines])]
        else:
            fixes[idiom] = ["def {}".format(idiom)]
    return fixes

def main():
